import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';


export interface ConfirmModalData {
    message: string;
    resolve: (value: boolean) => void;
}

/**
 * ConfirmModalService
 * Service to manage confirmation modals with Yes/No buttons
 */
@Injectable({
    providedIn: 'root'
})
export class ConfirmModalService {
    private modalDataSubject = new BehaviorSubject<ConfirmModalData | null>(null);
    public modalData$ = this.modalDataSubject.asObservable();

    constructor() { }

    /**
     * Show a confirmation modal with "Oui" / "Non" buttons
     * Returns a promise that resolves to true (Oui) or false (Non)
     */
    confirm(message: string): Promise<boolean> {
        return new Promise((resolve) => {
            this.modalDataSubject.next({
                message,
                resolve
            });
        });
    }

    /**
     * User clicked "Oui" - resolve with true and close modal
     */
    confirmYes(): void {
        const data = this.modalDataSubject.value;
        if (data) {
            data.resolve(true);
            this.modalDataSubject.next(null);
        }
    }

    /**
     * User clicked "Non" or closed modal - resolve with false and close modal
     */
    confirmNo(): void {
        const data = this.modalDataSubject.value;
        if (data) {
            data.resolve(false);
            this.modalDataSubject.next(null);
        }
    }

    /**
     * Close modal without action (same as "Non")
     */
    close(): void {
        this.confirmNo();
    }
}
